// tools/test/test-generators-registered.cjs

/**
 * ==============================================================================
 * MODULE: Generators Are Registered
 * DESCRIPTION:
 * Every script under tools/codegen/ that writes files is in the generator
 * registry (tools/build/generators.cjs), or named here with the reason it is
 * not. The parity table and the feature requirements table were generated by
 * hand only: `npm run gen`, the drift gate and the pre-commit
 * regeneration never ran them, and a manifest change reached dev with a stale
 * parity table (2026-11-23). The pre-commit hook must also regenerate before it
 * formats, so the regenerated files are formatted like the rest.
 * ==============================================================================
 */

'use strict';

const assert = require('assert');
const fs = require('fs');
const path = require('path');
const { GENERATORS } = require('../build/generators.cjs');

const ROOT = path.resolve(__dirname, '..', '..');

/** Scripts under tools/codegen/ that write files but are not generators of committed outputs. */
const NOT_GENERATORS = {
	'codegen/new-driver.js': 'scaffolds a new driver tree once, on request',
	'codegen/codegen-config-schema-metrics.cjs':
		'patches one block of the hand-written config.schema.json, which Prettier keeps formatting; test-config-schema.cjs fails when that block is stale'
};

const registered = new Set(GENERATORS.map((g) => g.script));
const missing = [];
for (const name of fs.readdirSync(path.join(ROOT, 'tools', 'codegen')).sort()) {
	if (!/\.(cjs|js)$/.test(name)) continue;
	const script = 'codegen/' + name;
	const source = fs.readFileSync(path.join(ROOT, 'tools', 'codegen', name), 'utf8');
	if (!/\bwriteFile(Sync)?\s*\(/.test(source)) continue;
	if (registered.has(script) || NOT_GENERATORS[script]) continue;
	missing.push(script);
}
assert.deepStrictEqual(
	missing,
	[],
	'register these generators in tools/build/generators.cjs: ' + missing.join(', ')
);

for (const g of GENERATORS) {
	assert.ok(
		fs.existsSync(path.join(ROOT, 'tools', g.script)),
		g.script + ' is registered but missing'
	);
	if (g.precommitSkip !== undefined)
		assert.ok(
			typeof g.precommitSkip === 'string' && g.precommitSkip.length > 0,
			g.script + ' must say why it is skipped'
		);
	if (g.precommitInputs !== undefined)
		assert.ok(
			Array.isArray(g.precommitInputs) && g.precommitInputs.length > 0,
			g.script + ' must name its inputs'
		);
}

const hook = fs.readFileSync(path.join(ROOT, '.husky', 'pre-commit'), 'utf8');
const regen = hook.indexOf('node tools/dev/regen-staged.cjs || exit 1');
const format = hook.indexOf('node tools/lint/format.cjs --staged');
assert.ok(regen !== -1, 'the pre-commit hook regenerates the projections of staged sources');
assert.ok(format !== -1 && regen < format, 'the hook regenerates before it formats');

console.log(
	`[OK] ${registered.size} generators registered, the pre-commit hook regenerates before formatting.`
);
